import itertools,json
jobs='ABCDE';published='ACEBD'
slot={'A':[4,8,0,2,0],'B':[6,4,5,0,5],'C':[2,6,4,6,0],'D':[8,7,9,6,0],'E':[3,3,1,6,5]}
t=[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]
# Breadth-first search gives minimum pair-exchange distance.
dist={published:0};front=[published]
for depth in (1,2):
 nxt=[]
 for p in front:
  for i,j in itertools.combinations(range(5),2):
   q=list(p);q[i],q[j]=q[j],q[i];q=''.join(q)
   if q not in dist:dist[q]=depth;nxt.append(q)
 front=nxt
classes={d:[] for d in range(3)}
for p,d in dist.items():
 pos={x:p.index(x)+1 for x in jobs}
 if pos['A']>=pos['D'] or pos['E'] in (2,3) or pos['D']==5:continue
 nominal=sum(slot[x][i] for i,x in enumerate(p))+sum(t[jobs.index(a)][jobs.index(b)] for a,b in zip(p,p[1:]))
 cost=nominal+6*max(0,pos['A']-2)+4*d+(5 if d==2 else 0)
 classes[d].append((cost,p))
best=min(item for c in classes.values() for item in c)
print(json.dumps({'roster':best[1],'score':best[0],'best_by_swaps':{str(d):min(c)[0] if c else None for d,c in classes.items()},'feasible_by_swaps':{str(d):len(c) for d,c in classes.items()}}))
print('feasible candidates',classes)
# Independently verify distances with n minus cycle count of permutation.
for p,d in dist.items():
 permutation=[published.index(x) for x in p];seen=set();cycles=0
 for i in range(5):
  if i not in seen:
   cycles+=1;j=i
   while j not in seen:seen.add(j);j=permutation[j]
 assert d==5-cycles

